@import url('https://fonts.googleapis.com/css2?family=Poppins:wght@700&family=Open+Sans:wght@400;600;700&display=swap');
.kv{font-family:'Open Sans',sans-serif;font-size:16px;line-height:1.6;color:#67757F;background:#D9DDEE;position:relative;width:100%;margin:0;overflow:hidden;-webkit-font-smoothing:antialiased}
.kv *{box-sizing:border-box}.kv h1,.kv h2,.kv h3,.kv p,.kv ul,.kv li{margin:0;padding:0}.kv ul{list-style:none}
.kv a{color:inherit;text-decoration:none;border:0;box-shadow:none}
.kv h1,.kv h2,.kv h3{font-family:Poppins,sans-serif;font-weight:700;line-height:1.2;text-transform:none;letter-spacing:0}
.kv .w{max-width:1180px;margin:0 auto;padding:0 24px}
.kv .bar{display:block;width:60px;height:3px;background:#FFFFFF;margin:18px 0 0}
.kv .btn{display:inline-block;padding:15px 30px;background:#1A5CE0;color:#FFFFFF;font:700 13px/1 'Open Sans',sans-serif;letter-spacing:.08em;text-transform:uppercase;border:0;border-radius:4px;transition:.2s}.kv .btn:hover{background:#000F23;color:#FFFFFF}
.kv .hero{position:relative;background:linear-gradient(90deg,#3E4E8A 0 50%,#3E4E8A 50% 100%);padding:150px 0 90px;color:#FFFFFF}
.kv .hero h1{color:#FFFFFF;font-size:clamp(34px,4.6vw,56px)}
.kv .hero .w{display:grid;grid-template-columns:1fr 1fr;gap:40px;align-items:center;position:relative}
.kv .hero .sub{margin-top:22px;font:700 18px/1.4 'Open Sans',sans-serif;color:#FFFFFF}
.kv .hero .lead{margin-top:14px;max-width:470px;opacity:.92}
.kv .hero .btn{margin-top:30px}
.kv .hero .ph{justify-self:end;width:min(100%,430px)}
.kv .hero .ph img{width:100%;height:auto;aspect-ratio:1/1;object-fit:cover;object-position:50% 20%;border-radius:50%;display:block;box-shadow:0 24px 50px rgba(0,0,0,.3)}
.kv .sec{padding:80px 0 90px;background:#D9DDEE}
.kv .sec.pre{padding-top:140px}
.kv .sec h2{font-size:clamp(28px,3.6vw,44px);text-align:center;color:#000F23}
.kv .sec .bar{margin:18px auto 0;background:#000F23}
